import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p64_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv_transpose1d_k3s1p0_cuda(torch::Tensor x, torch::Tensor weight);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose1d_k3s1p0_cuda", &conv_transpose1d_k3s1p0_cuda,
          "Transposed 1D conv specialized for kernel_size=3, stride=1, padding=0, groups=1, no bias");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// One thread per output element (n, oc, xo).
// Gather formulation: out[n,oc,xo] = sum_{ic,k} x[n,ic,xo-k] * w[ic,oc,k]for valid (xo-k) in [0,L).
// __launch_bounds__(256, 4) caps registers to ~64/thread for >=4 CTAs/SM on Ampere.
__global__ void __launch_bounds__(256, 4)
conv_transpose1d_k3s1_kernel(
    const float* __restrict__ x,// [N, Cin, L]
    const float* __restrict__ weight,  // [Cin, Cout, 3]  (PyTorch ConvTranspose1d layout)
    float* __restrict__ out,           // [N, Cout, L_out]  L_out = L+2
    const int N, const int Cin, const int Cout, const int L, const int L_out
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * Cout * L_out) return;

    const int xo = idx % L_out;
    const int oc = (idx / L_out) % Cout;
    const int n  = (idx / L_out) / Cout;

    float acc = 0.0f;

    // Precompute per-(n) and per-(oc) base pointers to minimize live index arithmetic in the loop.
    const float* x_n= x      + (n * Cin) * L;
    const float* w_oc = weight + oc * 3;          // stride between ic slices: Cout*3
    const int w_ic_stride = Cout * 3;

    for (int ic = 0; ic < Cin; ++ic) {
        const float* xi  = x_n  + ic * L;
        const float* wi  = w_oc + ic * w_ic_stride;

        // k=0: input position xi = xo;valid when xo   in [0, L)
        if ((unsigned)xo       < (unsigned)L) acc += xi[xo    ] * wi[0];
        // k=1: input position xi = xo-1;  valid when xo-1 in [0, L)
        if ((unsigned)(xo - 1) < (unsigned)L) acc += xi[xo - 1] * wi[1];
        // k=2: input position xi = xo-2;  valid when xo-2 in [0, L)
        if ((unsigned)(xo - 2) < (unsigned)L) acc += xi[xo - 2] * wi[2];
    }

    out[n * Cout * L_out + oc * L_out + xo] = acc;
}

torch::Tensor conv_transpose1d_k3s1p0_cuda(
    torch::Tensor x,
    torch::Tensor weight
) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(x.is_contiguous() && weight.is_contiguous(), "tensors must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 3 && weight.dim() == 3, "x and weight must be 3D");

    const int N    = x.size(0);
    const int Cin  = x.size(1);
    const int L    = x.size(2);
    const int Cout = weight.size(1);
    const int L_out = L + 2;  // stride=1, padding=0, kernel_size=3 -> (L-1)+3 = L+2

    auto out = torch::zeros({N, Cout, L_out}, x.options());

    const int total   = N * Cout * L_out;
    const int threads = 256;
    const int blocks= (total + threads - 1) / threads;

    conv_transpose1d_k3s1_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        N, Cin, Cout, L, L_out
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a transposed 1D convolution operation.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (int): Size of the convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int, optional): Padding applied to the input. Defaults to 0.
            output_padding (int, optional): Additional size added to one side of the output shape. Defaults to 0.
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv1d_transpose = nn.ConvTranspose1d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)
        self._ks = kernel_size
        self._stride = stride
        self._padding = padding
        self._output_padding = output_padding
        self._groups = groups
        self._use_bias = bias
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        _use_fast = (
                    x.is_cuda and
                    x.dtype == torch.float32 and
                    x.is_contiguous() and
                    self.conv1d_transpose.weight.is_contiguous() and
                    self._ks == 3 and
                    self._stride == 1 and
                    self._padding == 0 and
                    self._output_padding == 0 and
                    self._groups == 1 and
                    not self._use_bias
                )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if _use_fast:
            return _stark_get_extension().conv_transpose1d_k3s1p0_cuda(
            x, self.conv1d_transpose.weight
            )
        return self.conv1d_transpose(x)
        # <<<END_IMPROVE>>>
